SELECT setval(pg_get_serial_sequence('public.brands', 'id'), (SELECT max(id) FROM public.brands));

UPDATE public.brands b SET parent_brand_id = parent.id FROM (VALUES
  ('redmi', 'xiaomi'),
  ('poco', 'xiaomi')
) AS v(slug, parent_slug) JOIN public.brands parent ON parent.slug::text = v.parent_slug WHERE b.slug::text = v.slug;

