SELECT v.key, v.body_en, v.body_ur FROM (VALUES
  ('pta_status.pta_approved', 'The phone''s IMEI is registered with PTA and shows "Compliant" in DIRBS. It works on all Pakistani networks with no time limit.', 'اس فون کا IMEI پی ٹی اے کے پاس رجسٹرڈ ہے اور DIRBS میں "Compliant" دکھاتا ہے۔ یہ پاکستان کے تمام نیٹ ورکس پر بغیر کسی مدت کی حد کے کام کرتا ہے۔'),
  ('pta_status.non_pta', 'The IMEI is not registered with PTA. A local SIM works only for a limited period (currently about 60 days from first use). After that, the phone is blocked on Pakistani networks unless the PTA tax is paid and the phone is registered through DIRBS. Wi-Fi keeps working.', 'اس فون کا IMEI پی ٹی اے کے پاس رجسٹرڈ نہیں ہے۔ مقامی سم صرف محدود مدت تک کام کرتی ہے (فی الحال پہلے استعمال سے تقریباً 60 دن)۔ اس کے بعد فون پاکستانی نیٹ ورکس پر بند ہو جاتا ہے، جب تک پی ٹی اے ٹیکس ادا کر کے DIRBS کے ذریعے رجسٹریشن نہ کرائی جائے۔ وائی فائی کام کرتا رہتا ہے۔'),
  ('pta_status.cpid_patched', 'The IMEI has been changed or "patched" through an unofficial method to look approved. This is not PTA approval. These phones can be blocked at any time, and IMEI tampering is illegal in Pakistan. A DIRBS check often shows a different phone model than the one in hand.', 'اس فون کا IMEI غیر سرکاری طریقے سے تبدیل یا "پیچ" کیا گیا ہے تاکہ یہ منظور شدہ لگے۔ یہ پی ٹی اے کی منظوری نہیں ہے۔ ایسے فون کسی بھی وقت بند ہو سکتے ہیں، اور پاکستان میں IMEI میں چھیڑ چھاڑ غیر قانونی ہے۔ DIRBS چیک میں اکثر ہاتھ میں موجود فون کے بجائے کوئی دوسرا ماڈل نظر آتا ہے۔'),
  ('pta_status.unknown', 'The seller hasn''t confirmed the PTA status. Check it yourself before paying: dial *#06# to see the IMEI, then check it through an official PTA channel.', 'بیچنے والے نے پی ٹی اے اسٹیٹس کی تصدیق نہیں کی۔ ادائیگی سے پہلے خود چیک کریں: IMEI دیکھنے کے لیے *#06# ڈائل کریں، پھر اسے پی ٹی اے کے سرکاری ذریعے سے چیک کریں۔'),
  ('cpid.banner', 'CPID / patched phone: NOT PTA approved. It can be blocked on Pakistani networks at any time, and IMEI tampering is illegal in Pakistan. Daam never features or promotes these listings.', 'CPID / پیچ شدہ فون: پی ٹی اے سے منظور شدہ نہیں۔ یہ کسی بھی وقت پاکستانی نیٹ ورکس پر بند ہو سکتا ہے، اور پاکستان میں IMEI میں چھیڑ چھاڑ غیر قانونی ہے۔ دام ایسی لسٹنگز کو کبھی فیچر یا پروموٹ نہیں کرتا۔'),
  ('pta_reg_type.official_import', 'Imported officially by the brand or its distributor (box pack, usually with a brand warranty). Registered with PTA at import.', 'برانڈ یا اس کے ڈسٹری بیوٹر نے سرکاری طور پر درآمد کیا (باکس پیک، عموماً برانڈ وارنٹی کے ساتھ)۔ درآمد کے وقت پی ٹی اے کے پاس رجسٹرڈ ہوا۔'),
  ('pta_reg_type.individual_tax_paid', 'Brought into Pakistan by an individual, who then paid the PTA tax and registered the IMEI through DIRBS.', 'کسی فرد نے فون پاکستان لا کر پی ٹی اے ٹیکس ادا کیا اور DIRBS کے ذریعے IMEI رجسٹر کرایا۔'),
  ('pta_reg_type.unknown', 'The seller hasn''t said how the phone was registered.', 'بیچنے والے نے یہ نہیں بتایا کہ فون کیسے رجسٹر ہوا۔'),
  ('network_lock.factory_unlocked', 'Works with any carrier''s SIM. Whether it works on Pakistani networks still depends on its PTA status.', 'کسی بھی کمپنی کی سم کے ساتھ کام کرتا ہے۔ پاکستانی نیٹ ورکس پر چلنا پھر بھی اس کے پی ٹی اے اسٹیٹس پر منحصر ہے۔'),
  ('network_lock.carrier_locked', 'Locked to a foreign carrier. It won''t accept Pakistani SIMs unless it is officially unlocked.', 'کسی غیر ملکی نیٹ ورک کمپنی کے ساتھ لاک ہے۔ سرکاری طور پر ان لاک ہوئے بغیر یہ پاکستانی سم قبول نہیں کرے گا۔'),
  ('network_lock.jv', 'A carrier-locked iPhone made to work through an unofficial SIM-unlock method (a chip or eSIM workaround). It is not PTA approved, generally can''t be registered in the normal way, and network service can be unstable or stop after software updates.', 'کیریئر لاک آئی فون جسے غیر سرکاری سم ان لاک طریقے (چپ یا ای سم کا متبادل طریقہ) سے چلایا گیا ہے۔ یہ پی ٹی اے سے منظور شدہ نہیں، عام طریقے سے رجسٹر نہیں ہو سکتا، اور سافٹ ویئر اپ ڈیٹ کے بعد نیٹ ورک غیر مستحکم ہو سکتا ہے یا بند ہو سکتا ہے۔'),
  ('network_lock.unknown', 'The seller isn''t sure whether the phone is locked to a carrier. Test it with your own SIM before paying.', 'بیچنے والے کو یقین نہیں کہ فون کسی نیٹ ورک کمپنی کے ساتھ لاک ہے یا نہیں۔ ادائیگی سے پہلے اپنی سم ڈال کر چیک کریں۔'),
  ('pta_check.seller_declared', 'Seller says. Daam has not checked this phone''s PTA status. Check the IMEI yourself before paying.', 'بیچنے والے کے مطابق۔ دام نے اس فون کا پی ٹی اے اسٹیٹس چیک نہیں کیا۔ ادائیگی سے پہلے خود IMEI چیک کریں۔'),
  ('pta_check.daam_checked', 'A Daam moderator checked this phone''s IMEI on PTA''s official DVS and confirmed the model name matches. The check is valid for 30 days, so still check the IMEI in person before paying.', 'دام کے ایک موڈریٹر نے اس فون کا IMEI پی ٹی اے کی سرکاری DVS پر چیک کیا اور ماڈل کے نام کی تصدیق کی۔ یہ چیک 30 دن تک درست ہے، اس لیے ادائیگی سے پہلے خود بھی IMEI چیک کریں۔'),
  ('check_before_pay.intro', 'Before you pay, check the phone yourself. It takes two minutes.', 'ادائیگی سے پہلے فون خود چیک کریں۔ اس میں صرف دو منٹ لگتے ہیں۔'),
  ('check_before_pay.step_1', 'Dial *#06# on the phone to see its IMEI. Dual-SIM phones have two IMEIs, so check both.', 'فون پر *#06# ڈائل کر کے IMEI دیکھیں۔ ڈوئل سم فون میں دو IMEI ہوتے ہیں، دونوں چیک کریں۔'),
  ('check_before_pay.step_2', 'Check each 15-digit IMEI through an official PTA channel: SMS the IMEI to 8484, dial *8484#, or use PTA''s DVS website (dvs.pta.gov.pk) or the official DVS app.', 'ہر 15 ہندسوں والا IMEI پی ٹی اے کے سرکاری ذریعے سے چیک کریں: IMEI کو 8484 پر SMS کریں، *8484# ڈائل کریں، یا پی ٹی اے کی DVS ویب سائٹ (dvs.pta.gov.pk) یا سرکاری DVS ایپ استعمال کریں۔'),
  ('check_before_pay.step_3', 'Confirm the result says "Compliant" and that the model name matches the phone in your hand. A mismatch is the classic sign of a patched (CPID) phone.', 'تصدیق کریں کہ نتیجے میں "Compliant" لکھا ہو اور ماڈل کا نام آپ کے ہاتھ والے فون سے ملتا ہو۔ ماڈل کا نہ ملنا پیچ شدہ (CPID) فون کی عام نشانی ہے۔'),
  ('check_before_pay.step_4', 'Confirm the IMEI on the box matches the IMEI on the phone.', 'تصدیق کریں کہ ڈبے پر لکھا IMEI فون کے IMEI سے ملتا ہے۔'),
  ('check_before_pay.step_5', 'Never pay, or send a "token" or advance payment, before doing all of this.', 'یہ سب کرنے سے پہلے کبھی ادائیگی نہ کریں، نہ ہی "ٹوکن" یا ایڈوانس رقم بھیجیں۔'),
  ('safety.meetup.intro', 'Meeting a buyer or seller? A few simple habits keep you safe.', 'خریدار یا بیچنے والے سے مل رہے ہیں؟ چند آسان عادتیں آپ کو محفوظ رکھتی ہیں۔'),
  ('safety.meetup.public_place', 'Meet in a public place such as a mall, a market or a busy café.', 'عوامی جگہ پر ملیں، جیسے مال، مارکیٹ یا رش والا کیفے۔'),
  ('safety.meetup.daylight', 'Meet in daylight.', 'دن کی روشنی میں ملیں۔'),
  ('safety.meetup.bring_someone', 'Bring someone along.', 'کسی کو ساتھ لے کر جائیں۔'),
  ('safety.meetup.check_imei', 'Check the IMEI on 8484 and confirm the model matches before paying.', 'ادائیگی سے پہلے 8484 پر IMEI چیک کریں اور تصدیق کریں کہ ماڈل ملتا ہے۔'),
  ('safety.meetup.test_phone', 'Test calls, the camera, Face ID or fingerprint, charging and the speakers.', 'کالز، کیمرہ، فیس آئی ڈی یا فنگر پرنٹ، چارجنگ اور اسپیکرز چیک کریں۔'),
  ('safety.meetup.no_advance', 'Never send advance or "token" money.', 'کبھی ایڈوانس یا "ٹوکن" رقم نہ بھیجیں۔'),
  ('safety.meetup.verified_shops', 'For high-value phones, prefer Verified Shops.', 'مہنگے فونز کے لیے ویریفائیڈ شاپس کو ترجیح دیں۔'),
  ('safety.chat_start', 'Stay safe: meet in a public place, check the IMEI on 8484 before paying, and never send advance or "token" money.', 'محفوظ رہیں: عوامی جگہ پر ملیں، ادائیگی سے پہلے 8484 پر IMEI چیک کریں، اور کبھی ایڈوانس یا "ٹوکن" رقم نہ بھیجیں۔'),
  ('safety.scam.token_money', 'Asking for "token money" or an advance to "hold" a phone. Never pay before you have seen and checked the phone.', 'فون "ہولڈ" کرنے کے لیے "ٹوکن منی" یا ایڈوانس مانگنا۔ فون دیکھنے اور چیک کرنے سے پہلے کبھی ادائیگی نہ کریں۔'),
  ('safety.scam.easypaisa_first', 'Asking you to send money on Easypaisa or JazzCash first. Pay only in person, after checking.', 'پہلے ایزی پیسہ یا جاز کیش پر رقم بھیجنے کا کہنا۔ صرف آمنے سامنے، چیک کرنے کے بعد ادائیگی کریں۔'),
  ('safety.scam.courier', 'Offering courier or cash on delivery for an expensive phone you cannot inspect first.', 'کسی مہنگے فون کے لیے کوریئر یا کیش آن ڈیلیوری کی پیشکش، جسے آپ پہلے دیکھ نہ سکیں۔'),
  ('safety.scam.outside_links', 'Sending links to other websites or apps to "verify" a payment or the phone.', 'ادائیگی یا فون کی "تصدیق" کے لیے دوسری ویب سائٹس یا ایپس کے لنک بھیجنا۔'),
  ('safety.scam.fake_8484', 'Showing a screenshot of an 8484 result instead of letting you check the IMEI yourself.', 'آپ کو خود IMEI چیک کرنے دینے کے بجائے 8484 کے نتیجے کا اسکرین شاٹ دکھانا۔'),
  ('safety.scam.too_cheap', 'A price far below the usual market price. Daam holds listings priced under half the typical price for a moderator to review.', 'مارکیٹ کی عام قیمت سے بہت کم قیمت۔ دام عام قیمت کے آدھے سے کم والی لسٹنگز کو موڈریٹر کے جائزے کے لیے روک لیتا ہے۔'),
  ('safety.report', 'If something feels wrong, stop and report the listing or the user. Reports are private.', 'اگر کچھ غلط لگے تو رک جائیں اور لسٹنگ یا صارف کی رپورٹ کریں۔ رپورٹس خفیہ رہتی ہیں۔'),
  ('faq.pta_time_limit.q', 'How long does a Non-PTA phone work on a Pakistani SIM?', 'نان پی ٹی اے فون پاکستانی سم پر کتنی دیر چلتا ہے؟'),
  ('faq.pta_time_limit.a', 'Currently about 60 days from first use. After that it is blocked on Pakistani networks unless the PTA tax is paid and the phone is registered through DIRBS. Wi-Fi keeps working.', 'فی الحال پہلے استعمال سے تقریباً 60 دن۔ اس کے بعد یہ پاکستانی نیٹ ورکس پر بند ہو جاتا ہے، جب تک پی ٹی اے ٹیکس ادا کر کے DIRBS کے ذریعے رجسٹریشن نہ کرائی جائے۔ وائی فائی کام کرتا رہتا ہے۔'),
  ('faq.pta_cpid.q', 'Is a CPID or patched phone the same as PTA approved?', 'کیا CPID یا پیچ شدہ فون پی ٹی اے منظور شدہ جیسا ہے؟'),
  ('faq.pta_cpid.a', 'No. A patched phone''s IMEI was changed through an unofficial method. It is not PTA approval, it can be blocked at any time, and IMEI tampering is illegal in Pakistan.', 'نہیں۔ پیچ شدہ فون کا IMEI غیر سرکاری طریقے سے بدلا گیا ہوتا ہے۔ یہ پی ٹی اے کی منظوری نہیں، یہ کسی بھی وقت بند ہو سکتا ہے، اور پاکستان میں IMEI میں چھیڑ چھاڑ غیر قانونی ہے۔'),
  ('faq.pta_jv.q', 'What is a JV iPhone?', 'JV آئی فون کیا ہے؟'),
  ('faq.pta_jv.a', 'A carrier-locked iPhone made to work through an unofficial SIM-unlock method. It is not PTA approved, and network service can be unstable or stop after software updates.', 'کیریئر لاک آئی فون جسے غیر سرکاری سم ان لاک طریقے سے چلایا گیا ہو۔ یہ پی ٹی اے سے منظور شدہ نہیں، اور سافٹ ویئر اپ ڈیٹ کے بعد نیٹ ورک غیر مستحکم ہو سکتا ہے یا بند ہو سکتا ہے۔'),
  ('faq.daam_checked.q', 'What does "Checked by Daam" mean?', '"دام نے چیک کیا" کا کیا مطلب ہے؟'),
  ('faq.daam_checked.a', 'A Daam moderator checked the phone''s IMEI on PTA''s official DVS and confirmed the model matches. Everything else is what the seller says, so always check the IMEI yourself before paying.', 'دام کے موڈریٹر نے فون کا IMEI پی ٹی اے کی سرکاری DVS پر چیک کیا اور ماڈل کی تصدیق کی۔ باقی سب بیچنے والے کے مطابق ہے، اس لیے ادائیگی سے پہلے ہمیشہ خود IMEI چیک کریں۔'),
  ('faq.imei_private.q', 'Why does Daam ask for my IMEI?', 'دام میرا IMEI کیوں مانگتا ہے؟'),
  ('faq.imei_private.a', 'To catch duplicate and stolen phones and to let moderators check PTA status. It is encrypted and never shown publicly; buyers see only the last 4 digits.', 'ڈپلیکیٹ اور چوری شدہ فون پکڑنے اور موڈریٹرز کو پی ٹی اے اسٹیٹس چیک کرنے کے لیے۔ یہ خفیہ (encrypted) رکھا جاتا ہے اور کبھی عوامی طور پر نہیں دکھایا جاتا؛ خریدار صرف آخری 4 ہندسے دیکھتے ہیں۔'),
  ('faq.selling_free.q', 'Is it free to sell on Daam?', 'کیا دام پر بیچنا مفت ہے؟'),
  ('faq.selling_free.a', 'Yes. Individuals can have up to 3 active listings for free. Shops get a free plan with up to 50 active listings.', 'جی ہاں۔ افراد مفت میں 3 تک فعال لسٹنگز رکھ سکتے ہیں۔ دکانوں کو 50 تک فعال لسٹنگز کا مفت پلان ملتا ہے۔'),
  ('faq.listing_review.q', 'Why is my listing pending?', 'میری لسٹنگ زیرِ جائزہ کیوں ہے؟'),
  ('faq.listing_review.a', 'During launch, a moderator reviews every listing before it goes live. We aim to review within 2 hours, between 10am and 10pm.', 'لانچ کے دوران ہر لسٹنگ لائیو ہونے سے پہلے موڈریٹر دیکھتا ہے۔ ہماری کوشش ہے کہ صبح 10 سے رات 10 بجے کے درمیان 2 گھنٹے میں جائزہ ہو جائے۔'),
  ('faq.contact_number.q', 'Why do I need to log in to see a seller''s number?', 'بیچنے والے کا نمبر دیکھنے کے لیے لاگ اِن کیوں ضروری ہے؟'),
  ('faq.contact_number.a', 'It stops spammers from collecting numbers. Each number reveal is logged and limited.', 'اس سے اسپیمرز نمبر جمع نہیں کر پاتے۔ ہر نمبر دکھانے کا ریکارڈ رکھا جاتا ہے اور اس کی حد مقرر ہے۔')
) AS v(key, body_en, body_ur);

SELECT v.key, v.value::jsonb FROM (VALUES
  ('allow_cpid_listings', 'true'),
  ('max_free_listings_individual', '3'),
  ('premoderation_enabled', 'true'),
  ('scam_price_ratio', '0.5'),
  ('listing_expiry_days', '30'),
  ('daam_min_comparables', '5')
) AS v(key, value);

