  IF (SELECT count(*) FROM public.cities) <> 29 THEN RAISE EXCEPTION 'Seed count mismatch: cities'; END IF;
  IF (SELECT count(*) FROM public.areas) <> 86 THEN RAISE EXCEPTION 'Seed count mismatch: areas'; END IF;
  IF (SELECT count(*) FROM public.series) <> 42 THEN RAISE EXCEPTION 'Seed count mismatch: series'; END IF;
  IF (SELECT count(*) FROM public.models) <> 332 THEN RAISE EXCEPTION 'Seed count mismatch: models'; END IF;
  IF (SELECT count(*) FROM public.model_aliases) <> 1417 THEN RAISE EXCEPTION 'Seed count mismatch: model_aliases'; END IF;
  IF (SELECT count(*) FROM public.model_variants) <> 704 THEN RAISE EXCEPTION 'Seed count mismatch: model_variants'; END IF;
  IF (SELECT count(*) FROM public.model_colors) <> 393 THEN RAISE EXCEPTION 'Seed count mismatch: model_colors'; END IF;
  IF (SELECT count(*) FROM public.content_blocks) <> 52 THEN RAISE EXCEPTION 'Seed count mismatch: content_blocks'; END IF;
  IF (SELECT count(*) FROM public.app_settings) <> 6 THEN RAISE EXCEPTION 'Seed count mismatch: app_settings'; END IF;
